def consumer():
    for mode in ('defective_goods','defective_service','late_delivery','claim'):
        claim=mode=='claim';key='claim_consumer' if claim else 'pretense_consumer_'+mode
        title={'defective_goods':'Претензия в связи с недостатками приобретённого товара','defective_service':'Претензия в связи с недостатками работ или услуг','late_delivery':'Претензия в связи с нарушением срока передачи оплаченного товара','claim':'Исковое заявление о защите прав потребителя'}[mode]
        fs,bs=people('Истец' if claim else 'Потребитель','Ответчик' if claim else 'Продавец или исполнитель',claim);bs += [b(title,'title')]
        items(fs,bs,row('purchase','Приобретение товара, работ или услуг','Что, у кого и когда приобретено или заказано? Назовите товар либо предмет работ или услуг и реквизиты договора.'),
            row('amount','Уплаченная сумма','Какую сумму вы фактически уплатили в рублях?', 'money'),
            row('payment_evidence','Подтверждение оплаты','Чем подтверждается оплата? Укажите реквизиты чека, перевода или другие имеющиеся сведения.'),
            row('personal_use','Цель приобретения','Товар, работа или услуга приобретались для личных нужд? Опишите цель приобретения.'))
        if mode=='late_delivery':
            items(fs,bs,row('delivery_due','Согласованный срок передачи','Какой срок передачи товара согласован и чем это подтверждается?'),
                row('delivery_status','Состояние исполнения','Передан ли товар сейчас, в какой части и когда?'))
        else:
            items(fs,bs,row('defects','Выявленные недостатки','Какие именно недостатки обнаружены и когда? Укажите известные сроки годности или гарантии, если они относятся к ситуации.'),
                row('defect_evidence','Подтверждение недостатков','Чем подтверждаются недостатки? Укажите имеющиеся документы, фотографии, результаты проверки или экспертизы.'),
                row('category','Характеристики приобретения','Какие вид, марка, модель товара или конкретный вид работ/услуг известны? Это нужно для проверки применимых правил.'))
        items(fs,bs,row('facts','Развитие ситуации','Какие ещё обстоятельства важны: даты обращений, последствия, проверка качества, ответы продавца?'),
            row('seller_response','Обращения к продавцу или исполнителю','Какие требования уже предъявлялись продавцу или исполнителю и каков его ответ?'))
        if claim: claim_end(fs,bs)
        else:
            items(fs,bs,row('requests','Требование потребителя','Какой конкретный результат вы выбираете: возврат оплаты, замена, устранение недостатков или другое? Несовместимые варианты одновременно не включаем.'),
                row('additional_claims','Дополнительные требования и расчёт','Заявляете ли подтверждённые убытки или другие суммы? Укажите основание и расчёт отдельно либо ответьте «нет».'),
                row('payment','Способ исполнения денежного требования','Как продавец может вернуть деньги? Неизвестные реквизиты можно дополнить позднее.'))
        save(key,title,'claim' if claim else 'pretense',fs,bs,[ZPP,GPK] if claim else [ZPP])


